design.css:
/* [VIA:DESIGN:v0103] Veritas Header 視覺:只動顏色 · 字體 · 邊角 · 頁首;版面 · 功能 · 燈四色不動(值全來自 :root token) */
:root{--paper:var(--panel);--paper2:var(--chip);--ink:var(--txt);--mute:var(--dim);--blue:var(--acc);--co:var(--seal);--soft:var(--zebra);--r:var(--radius)}
html body{background:var(--bg);color:var(--txt)}
a{color:var(--acc)}
header,.top,.via-hd{background:var(--head);color:var(--head-txt);border-bottom:1px solid var(--line)}
header h1,.top h1,.brand .bt b,.via-brand{font-family:var(--serif);font-weight:600;letter-spacing:.07em;color:var(--head-txt)}
header h1::before,.top h1::before{content:var(--tag);display:inline-block;margin-right:8px;padding:1px 7px;background:var(--seal);color:#fff;font-family:var(--mono);font-size:var(--fs-note);font-weight:400;letter-spacing:.14em;vertical-align:middle}
header h1::after,.top h1::after{content:var(--brand);display:block;margin-top:2px;font-family:var(--mono);font-size:var(--fs-note);font-weight:400;letter-spacing:.2em;text-transform:uppercase;color:var(--caption)}
header small,.top h1 small,.meta,.brand .bt small,.via-caption{font-family:var(--mono);letter-spacing:.08em;color:var(--dim)}
aside,.side{background:var(--panel-2);border-color:var(--line)}
label,.dim,.via-note,.side label{color:var(--nav-dim)}
.card,.kpi,.g3s,.side details,.chip{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}
.card>b,.card h2,.hd,.side summary,.kpi b{color:var(--txt)}
button,.btn,.pages button,.tabs button,.sysbtn,.bar button,.fold-btn,#l121-fold{background:var(--panel);color:var(--txt);border:1px solid var(--line);border-radius:5px;font-family:var(--mono);letter-spacing:.06em}
button.p,.btn.pri,.tabs button.on,.pages button.on,.sysbtn.on{background:var(--acc);color:#fff;border-color:var(--acc);box-shadow:none}
.sysbtn.on small,.sysbtn.on b,.btn.pri small{color:#fff}
input,select,textarea{background:var(--panel);color:var(--txt);border:1px solid var(--line);border-radius:5px}
table{background:var(--panel)}
th{background:var(--head);color:var(--head-txt);border-color:var(--line);font-family:var(--mono);letter-spacing:.08em}
td{border-color:var(--hair)}
tr:nth-child(even){background:var(--zebra)}
.seal{background:var(--seal);color:#fff}
